<script setup>
import { onMounted, reactive, ref } from 'vue'
const props=defineProps({api:{type:Function,required:true}})
const tabs=[['logs','重置日志'],['stats','周期统计'],['user','用户历史'],['manual','人工重置']]
const tab=ref('logs'),loading=ref(false),error=ref(''),logs=ref([]),logsTotal=ref(0),stats=ref(null),userHistory=ref(null),userId=ref(''),days=ref(30),page=ref(1)
const filters=reactive({user_email:'',reset_type:'',trigger_source:'',start_date:'',end_date:''})
const resetTypes=[['','全部类型'],['monthly','月度'],['yearly','年度'],['onetime','一次性'],['manual','手动']]
const sources=[['','全部来源'],['auto','自动'],['manual','人工'],['cron','定时任务']]
const resetForm=reactive({user_id:'',reason:''})
const when=value=>value?new Date(value).toLocaleString('zh-CN'):'—'
const bytes=value=>{const n=Number(value||0);if(n>=1024**3)return `${(n/1024**3).toFixed(2)} GB`;if(n>=1024**2)return `${(n/1024**2).toFixed(2)} MB`;return `${n.toLocaleString()} B`}
async function load(){loading.value=true;error.value='';try{if(tab.value==='logs'){const q=new URLSearchParams({page:String(page.value),per_page:'25'});for(const [k,v]of Object.entries(filters))if(v)q.set(k,v);const result=await props.api(`traffic-reset/logs?${q}`);logs.value=result.data||[];page.value=result.pagination?.current_page||page.value;logsTotal.value=result.pagination?.total||0}else if(tab.value==='stats')stats.value=await props.api(`traffic-reset/stats?days=${days.value}`);else if(tab.value==='user'){if(!userId.value)throw new Error('请输入用户 ID。');userHistory.value=await props.api(`traffic-reset/user/${encodeURIComponent(userId.value)}/history?limit=50`)}}catch(e){error.value=e.message}finally{loading.value=false}}
function changeTab(id){tab.value=id;page.value=1;if(id==='logs'||id==='stats')load()}
async function manualReset(){if(!resetForm.user_id)return;if(!window.confirm(`确认重置用户 ID ${resetForm.user_id} 的流量？此操作会立即写入测试库并影响用户剩余额度。`))return;loading.value=true;error.value='';try{await props.api('traffic-reset/reset-user',{method:'POST',body:{user_id:Number(resetForm.user_id),reason:resetForm.reason||undefined}});tab.value='user';userId.value=resetForm.user_id;await load()}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load)
</script>
<template><section class="content-view reset-view"><div class="page-title-row"><div><p class="eyebrow">INFRASTRUCTURE / TRAFFIC RESET</p><h1>流量重置<span class="title-period">.</span></h1><p class="page-subtitle">追踪自动重置记录、查看用户历史或执行人工重置</p></div></div><div class="gift-tabs"><button v-for="[id,name] in tabs" :key="id" :class="{selected:tab===id}" @click="changeTab(id)">{{name}}</button></div><div v-if="error" class="api-error"><span>!</span><div><b>流量重置操作失败</b><p>{{error}}</p></div><button @click="load">重试</button></div>
<div v-if="tab==='logs'"><div class="reset-filters"><input v-model="filters.user_email" placeholder="用户邮箱"/><select v-model="filters.reset_type"><option v-for="[v,l] in resetTypes" :key="v" :value="v">{{l}}</option></select><select v-model="filters.trigger_source"><option v-for="[v,l] in sources" :key="v" :value="v">{{l}}</option></select><input v-model="filters.start_date" type="date"/><input v-model="filters.end_date" type="date"/><button @click="page=1;load()">筛选</button></div><div class="users-table-wrap"><div v-if="loading" class="table-state">正在读取重置日志…</div><div v-else-if="!logs.length" class="table-state">没有符合条件的记录。</div><table v-else class="users-table"><thead><tr><th>用户</th><th>重置类型</th><th>触发来源</th><th>旧流量</th><th>新流量</th><th>重置时间</th><th>原因</th></tr></thead><tbody><tr v-for="log in logs" :key="log.id"><td>{{log.user_email}}<small class="order-id">ID {{log.user_id}}</small></td><td>{{log.reset_type_name||log.reset_type}}</td><td>{{log.trigger_source_name||log.trigger_source}}</td><td>{{log.old_traffic?.formatted||bytes(log.old_traffic?.total)}}</td><td>{{log.new_traffic?.formatted||bytes(log.new_traffic?.total)}}</td><td>{{when(log.reset_time)}}</td><td>{{log.metadata?.reason||'—'}}</td></tr></tbody></table></div><div class="table-pagination"><span>第 {{page}} 页 · 共 {{logsTotal}} 条</span><div><button :disabled="page<=1||loading" @click="page--;load()">← 上一页</button><button :disabled="page*25>=logsTotal||loading" @click="page++;load()">下一页 →</button></div></div></div>
<div v-else-if="tab==='stats'"><div class="reset-filters"><label>统计天数<select v-model.number="days"><option :value="7">最近 7 天</option><option :value="30">最近 30 天</option><option :value="90">最近 90 天</option><option :value="365">最近一年</option></select></label><button @click="load">更新</button></div><div v-if="loading" class="table-state">正在计算统计…</div><div v-else-if="stats" class="metric-grid stats-metrics"><article v-for="[key,label] in [['total_resets','重置总数'],['auto_resets','自动重置'],['manual_resets','人工重置'],['cron_resets','定时重置']]" :key="key" class="metric-card"><div class="metric-top">{{label}}</div><div class="metric-value">{{stats[key]||0}}</div></article></div></div>
<div v-else-if="tab==='user'"><form class="reset-filters" @submit.prevent="load"><input v-model="userId" type="number" min="1" placeholder="用户 ID" required/><button>读取历史</button></form><div v-if="loading" class="table-state">正在读取用户历史…</div><template v-else-if="userHistory"><article class="data-panel reset-user-card"><b>{{userHistory.user?.email}}</b><span>ID {{userHistory.user?.id}}</span><span>累计重置 {{userHistory.user?.reset_count||0}} 次</span><span>最近重置 {{when(userHistory.user?.last_reset_at)}}</span><span>下次重置 {{when(userHistory.user?.next_reset_at)}}</span></article><div class="users-table-wrap"><div v-if="!userHistory.history?.length" class="table-state">该用户没有重置记录。</div><table v-else class="users-table"><thead><tr><th>类型</th><th>时间</th><th>旧流量</th><th>触发来源</th><th>原因</th></tr></thead><tbody><tr v-for="r in userHistory.history" :key="r.id"><td>{{r.reset_type_name}}</td><td>{{when(r.reset_time)}}</td><td>{{r.old_traffic?.formatted||bytes(r.old_traffic?.total)}}</td><td>{{r.trigger_source_name}}</td><td>{{r.metadata?.reason||'—'}}</td></tr></tbody></table></div></template></div>
<div v-else class="reset-manual-panel"><div><p class="eyebrow">MANUAL / RESET</p><h2>人工重置用户流量</h2><p>仅重置用户当前周期流量计数；重置会写入审计记录，并立刻影响用户可用流量。</p></div><form class="user-form" @submit.prevent="manualReset"><label>用户 ID<input v-model="resetForm.user_id" type="number" min="1" required/></label><label>原因（选填）<textarea v-model="resetForm.reason" rows="3" maxlength="255" placeholder="填写操作原因，写入重置日志"></textarea></label><button class="save-button reset-danger" :disabled="loading">{{loading?'正在重置…':'重置流量'}}</button></form></div>
<div class="footer-note"><span>XB CONTROL ROOM</span><span>人工重置会写入测试数据库 <i>·</i> 操作前会再次确认</span></div></section></template>
